css:
.sw {--sh-card:0 0 0 1px rgb(0 0 0/.3);--sh-plate:0 .5px 1px 1px rgb(0 0 0/.3);--sh-overlay:0 3px 8px rgb(0 0 0/.13),0 2px 5px rgb(0 0 0/.13),0 1px 1px rgb(0 0 0/.13);position:relative;display:inline-flex;height:16px;width:28px;flex-shrink:0;cursor:pointer;align-items:center;border-radius:9999px;border:var(--spacing-hairline) solid var(--color-border-2);background:var(--color-muted);padding:1.5px;transition:background-color 150ms,border-color 150ms;box-sizing:border-box}
:where([data-doop-theme="light"]) .sw {--sh-card:0 0 0 .5px rgb(0 0 0/.11);--sh-plate:0 1px 2px rgb(0 0 0/.05);--sh-overlay:0 6px 18px rgb(0 0 0/.03),0 3px 9px rgb(0 0 0/.04),0 1px 1px rgb(0 0 0/.05);}
.sw .th {width:12px;height:12px;border-radius:9999px;background:var(--color-primary-foreground);box-shadow:var(--sh-plate);transition:transform 150ms cubic-bezier(.23,1,.32,1)}
.sw[data-checked="true"] {border-color:transparent;background:var(--color-primary);--focus-ring:var(--color-primary-foreground)}
.sw[data-checked="true"] .th {transform:translateX(12px)}
.sw[data-focus="true"] {outline:1px solid var(--focus-ring,var(--color-ring));outline-offset:-1px}
.sw[data-disabled="true"] {cursor:not-allowed;opacity:.55}
